<template>
  <MarketplaceLayout><main class="market-container green-community community-detail-page"><RouterLink to="/community">Về cộng đồng</RouterLink><h1 v-if="loading||error">Bài viết cộng đồng</h1><ResourceState v-if="loading||error" resource="bài viết" :loading="loading" :error="Boolean(error)" :error-message="error" :not-found="notFound" recovery-to="/community" recovery-label="Về cộng đồng" @retry="load"/>
    <template v-else-if="post"><article class="community-card"><div class="community-labels"><span class="community-label">{{ postTypes[post.postType] }}</span><span>{{ topics[post.topic] }}</span><span v-if="post.pinned">Thông báo được ghim</span></div><h1>{{ post.title }}</h1><p class="community-card-meta">{{ post.authorName }} · {{ roleLabels[post.authorRole] }} · <time :datetime="post.createdAt">{{ date(post.createdAt) }}</time></p><p v-if="post.updatedAt!==post.createdAt" class="community-hint">Cập nhật {{ date(post.updatedAt) }}</p>
      <p v-if="post.postType==='PLANT_HELP'" class="community-help-state">{{ helpStates[post.helpStatus] }}</p><dl v-if="post.postType==='PLANT_HELP'&&Object.values(post.care).some(Boolean)" class="community-care-data"><template v-for="([label],key) in careFields" :key="key"><div v-if="post.care[key]"><dt>{{ label }}</dt><dd>{{ post.care[key] }}</dd></div></template></dl>
      <p class="community-post-body">{{ post.body }}</p><div v-if="post.images.length" class="community-card-images"><CatalogImage v-for="(image,i) in post.images" :key="image.id" :src="image.url" :alt="'Ảnh '+(i+1)+' của bài '+post.title" ratio="4/3"/></div>
      <p v-if="post.locked" class="community-hint">Thảo luận đã đóng. Bạn vẫn có thể đọc nội dung công khai.</p><div v-if="owns(post)&&!post.locked" class="community-actions"><RouterLink class="button button-outline" :to="'/community/posts/'+post.id+'/edit'">Chỉnh sửa bài viết</RouterLink><button type="button" :disabled="busy" @click="confirmDelete({kind:'post',item:post})">Xóa bài viết của tôi</button></div>
    <ReportContent v-if="isAuthenticated" kind="POST" :id="post.id"/><PostInteractions :post="post" @loaded="activity=$event" @changed="activity=$event"/><div v-if="canChoose&&!post.locked" class="community-actions"><button type="button" :disabled="busy" @click="changeStatus(post.helpStatus==='RESOLVED'?'OPEN':'RESOLVED')">{{ post.helpStatus==='RESOLVED'?'Mở lại vấn đề':'Tôi xác nhận đã giải quyết' }}</button><button v-if="post.acceptedCommentId" type="button" :disabled="busy" @click="chooseAnswer(null)">Bỏ chọn giải pháp</button></div><ProductLinksEditor v-if="owns(post)&&!post.locked&&['seller','admin'].includes(user?.role)" :post="post" :products="activity?.products||[]" @saved="refreshPost"/></article>
    <section class="community-comments community-panel" aria-labelledby="comments-title"><h2 id="comments-title">Cùng trao đổi</h2><ResourceState v-if="commentLoading||commentError" resource="bình luận" :loading="commentLoading" :error="Boolean(commentError)" :error-message="commentError" @retry="loadComments"/>
      <template v-else><p v-if="!comments.content.length" class="community-hint">Chưa có bình luận. Chia sẻ điều bạn biết để cùng giúp góc xanh này.</p><article v-for="c in comments.content" :id="'comment-'+c.id" :key="c.id" class="community-comment"><div class="community-card-meta"><strong>{{ c.authorName }}</strong><span class="community-label">{{ roleLabels[c.authorRole] }}</span><time :datetime="c.createdAt">{{ date(c.createdAt) }}</time></div><span v-if="c.id===post.acceptedCommentId" class="community-label">Tác giả chọn là giải pháp hữu ích</span>
        <form v-if="editing===c.id" class="community-comment-form" @submit.prevent="editComment(c)"><label :for="'edit-comment-'+c.id">Chỉnh sửa bình luận</label><textarea :id="'edit-comment-'+c.id" v-model="editBody" required maxlength="3000" rows="4"/><div class="community-actions"><button class="button button-outline" :disabled="busy">Lưu bình luận</button><button type="button" class="button button-outline" :disabled="busy" @click="editing=null">Hủy</button></div></form><p v-else>{{ c.body }}</p><div v-if="owns(c)&&editing!==c.id&&!post.locked" class="community-actions"><button type="button" :disabled="busy" @click="editing=c.id;editBody=c.body">Sửa bình luận</button><button type="button" :disabled="busy" @click="confirmDelete({kind:'comment',item:c})">Xóa bình luận</button></div>
      <ReportContent v-if="isAuthenticated" kind="COMMENT" :id="c.id"/><div v-if="canChoose&&!post.locked" class="community-actions"><button type="button" :disabled="busy" :aria-pressed="post.acceptedCommentId===c.id" @click="chooseAnswer(c.id)">{{ post.acceptedCommentId===c.id?'Đã chọn là hữu ích':'Chọn là giải pháp hữu ích' }}</button></div></article><nav v-if="comments.totalPages>1" class="community-actions" aria-label="Phân trang bình luận"><button class="button button-outline" :disabled="page===0||busy" @click="page--;loadComments()">Trước</button><span>Trang {{ page+1 }} / {{ comments.totalPages }}</span><button class="button button-outline" :disabled="page+1>=comments.totalPages||busy" @click="page++;loadComments()">Sau</button></nav></template>
      <p v-if="submitError" ref="submitErrorBox" tabindex="-1" role="alert">{{ submitError }}</p><p v-if="message" role="status">{{ message }}</p><form v-if="isAuthenticated&&!post.locked" class="community-comment-form" @submit.prevent="sendComment"><label for="comment-body">Bình luận của bạn</label><textarea id="comment-body" v-model="body" maxlength="3000" required rows="4" :disabled="busy"/><button class="button button-primary" :disabled="busy||!body.trim()">{{ busy?'Đang gửi…':'Gửi bình luận' }}</button></form><p v-else-if="!isAuthenticated"><RouterLink :to="{path:'/login',query:{redirect:route.fullPath}}">Đăng nhập để bình luận</RouterLink></p>
    </section></template>
    <ConfirmAction ref="confirmation" :title="deleting?.kind==='post'?'Xóa bài viết của bạn?':'Xóa bình luận của bạn?'" description="Nội dung sẽ không còn hiển thị công khai. Thao tác chỉ được xác nhận sau khi máy chủ xử lý." confirm-label="Xóa nội dung" :busy="busy" :error="deleteError" @confirm="remove"/>
  </main></MarketplaceLayout>
</template>
<script setup>
import {ref,computed,watch,onBeforeUnmount,nextTick} from 'vue';import {useRoute,useRouter} from 'vue-router';import MarketplaceLayout from '../../../layouts/MarketplaceLayout.vue';import ResourceState from '../../../components/marketplace/ResourceState.vue';import CatalogImage from '../../../components/marketplace/CatalogImage.vue';import ReportContent from '../../../components/community/ReportContent.vue';import PostInteractions from '../../../components/community/PostInteractions.vue';import ProductLinksEditor from '../../../components/community/ProductLinksEditor.vue';import ConfirmAction from '../../../components/community/ConfirmAction.vue';import {marketplaceRequest as request} from '../../../services/marketplace.js';import {topics,date} from '../../../services/discussions.js';import {postTypes,helpStates,careFields,roleLabels} from '../../../services/community.js';import {useAuth} from '../../../composables/useAuth.js';import '../../../css/community.css';
const route=useRoute(),router=useRouter(),{user,isAuthenticated}=useAuth(),post=ref(null),comments=ref({content:[],totalPages:0}),loading=ref(false),error=ref(''),notFound=ref(false),commentLoading=ref(false),commentError=ref(''),submitError=ref(''),submitErrorBox=ref(null),message=ref(''),busy=ref(false),body=ref(''),page=ref(0),editing=ref(null),editBody=ref(''),confirmation=ref(null),deleting=ref(null),deleteError=ref('');let generation=0,commentGeneration=0,requestKey=crypto.randomUUID();
const activity=ref(null),canChoose=computed(()=>post.value&&owns(post.value)&&['QUESTION','PLANT_HELP'].includes(post.value.postType));
const owns=item=>isAuthenticated.value&&item.authorId===user.value?.id;
async function refreshPost(){const ticket=generation;try{const result=await request('/community/posts/'+post.value.id);if(ticket===generation)post.value=result;}catch(e){if(ticket===generation)submitError.value=e.message;}}
function chooseAnswer(commentId){return mutate(()=>request('/account/community/posts/'+post.value.id+'/answer','PUT',{commentId,revision:post.value.revision}),'Đã lưu lựa chọn giải pháp.');}
function changeStatus(status){return mutate(()=>request('/account/community/posts/'+post.value.id+'/help-status','PUT',{status,revision:post.value.revision}),'Đã lưu trạng thái do bạn xác nhận.');}
async function load(){const ticket=++generation;post.value=null;activity.value=null;loading.value=true;error.value='';notFound.value=false;body.value='';page.value=0;editing.value=null;submitError.value='';message.value='';requestKey=crypto.randomUUID();try{const result=await request('/community/posts/'+encodeURIComponent(route.params.id));if(ticket===generation){post.value=result;await loadComments();}}catch(e){if(ticket===generation){notFound.value=e.status===404;error.value=notFound.value?'Bài viết không tồn tại hoặc không còn công khai.':e.message;}}finally{if(ticket===generation)loading.value=false;}}
async function loadComments(){const ticket=++commentGeneration,parent=generation;commentLoading.value=true;commentError.value='';try{const result=await request('/community/posts/'+encodeURIComponent(route.params.id)+'/comments?page='+page.value);if(ticket===commentGeneration&&parent===generation)comments.value=result;}catch(e){if(ticket===commentGeneration&&parent===generation)commentError.value=e.message;}finally{if(ticket===commentGeneration&&parent===generation)commentLoading.value=false;}}
async function mutate(action,success){if(busy.value)return;busy.value=true;submitError.value='';message.value='';const ticket=generation;try{await action();if(ticket!==generation)return;const result=await request('/community/posts/'+post.value.id);if(ticket!==generation)return;message.value=success;post.value=result;await loadComments();}catch(e){if(ticket===generation){submitError.value=e.message;await nextTick();submitErrorBox.value?.focus();}}finally{busy.value=false;}}
function sendComment(){return mutate(async()=>{await request('/account/community/posts/'+post.value.id+'/comments','POST',{body:body.value,requestKey});body.value='';requestKey=crypto.randomUUID();page.value=Math.floor((comments.value.totalElements||0)/10);},'Đã lưu bình luận.');}
function editComment(c){return mutate(async()=>{await request('/account/community/comments/'+c.id,'PUT',{body:editBody.value,revision:c.revision});editing.value=null;},'Đã lưu bình luận.');}
function confirmDelete(target){deleting.value=target;deleteError.value='';confirmation.value.open();}
async function remove(){if(busy.value)return;busy.value=true;deleteError.value='';const target=deleting.value;try{await request('/account/community/'+(target.kind==='post'?'posts/':'comments/')+target.item.id+'?revision='+target.item.revision,'DELETE');confirmation.value.close();if(target.kind==='post')await router.push('/community');else{post.value=await request('/community/posts/'+post.value.id);await loadComments();message.value='Đã xóa bình luận.';}}catch(e){deleteError.value=e.message;}finally{busy.value=false;}}
watch(()=>route.params.id,load,{immediate:true});onBeforeUnmount(()=>{generation++;commentGeneration++;});
watch(()=>user.value?.id,()=>{body.value='';editBody.value='';editing.value=null;activity.value=null;submitError.value='';requestKey=crypto.randomUUID();});
</script>
